using Timer = System.Threading.Timer;
using System.Collections.Concurrent;
namespace ExcelApp.Data;
public sealed class Watcher : IDisposable
{
    readonly Func<IReadOnlyList<IngestRecipe>> recipes; readonly Action<string,IngestRecipe> ready; readonly List<FileSystemWatcher> watchers=new();
    readonly ConcurrentDictionary<string,DateTime> queued=new(StringComparer.OrdinalIgnoreCase); readonly ConcurrentDictionary<string,byte> checking=new(StringComparer.OrdinalIgnoreCase); Timer? scanTimer; readonly CancellationTokenSource stop=new();
    public Watcher(Func<IReadOnlyList<IngestRecipe>> recipes,Action<string,IngestRecipe> ready) {this.recipes=recipes;this.ready=ready;}
    public void Start() {foreach(var folder in recipes().SelectMany(r=>r.Folders).Distinct(StringComparer.OrdinalIgnoreCase)) {if(!Directory.Exists(folder)) continue; var w=new FileSystemWatcher(folder) {IncludeSubdirectories=false,NotifyFilter=NotifyFilters.FileName|NotifyFilters.Size|NotifyFilters.LastWrite}; w.Created+=Changed;w.Changed+=Changed;w.Renamed+=Renamed;w.EnableRaisingEvents=true;watchers.Add(w);} Scan();scanTimer=new Timer(_=>Scan(),null,TimeSpan.FromMinutes(5),TimeSpan.FromMinutes(5));}
    void Changed(object sender,FileSystemEventArgs e)=>Consider(e.FullPath); void Renamed(object sender,RenamedEventArgs e)=>Consider(e.FullPath);
    public void Scan() {foreach(var folder in recipes().SelectMany(r=>r.Folders).Distinct(StringComparer.OrdinalIgnoreCase)) {try {foreach(var file in Directory.EnumerateFiles(folder)) Consider(file);} catch(IOException) {} catch(UnauthorizedAccessException) {}}}
    void Consider(string path) {if(!recipes().Any(r=>r.Folders.Any(f=>string.Equals(Path.GetFullPath(f).TrimEnd('\\'),Path.GetDirectoryName(path)?.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase)) && r.Patterns.Any(p=>Recognizer.Matches(Path.GetFileName(path),p)))) return; if(!checking.TryAdd(path,0)) return; _=Task.Run(async()=> {try {long size=-1;DateTime time=default;int stable=0;while(stable<3) {stop.Token.ThrowIfCancellationRequested();var info=new FileInfo(path);if(!info.Exists) return;if(info.Length==size && info.LastWriteTimeUtc==time) stable++;else {size=info.Length;time=info.LastWriteTimeUtc;stable=1;} if(stable<3) await Task.Delay(2000,stop.Token);} using(new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)) {} if(queued.TryGetValue(path,out var old) && old==time) return; queued[path]=time; var first=recipes().FirstOrDefault(r=>r.Folders.Any(f=>string.Equals(Path.GetFullPath(f).TrimEnd('\\'),Path.GetDirectoryName(path)?.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase)) && r.Patterns.Any(p=>Recognizer.Matches(Path.GetFileName(path),p))); if(first!=null) ready(path,first); } catch(IOException) {} catch(UnauthorizedAccessException) {} catch(OperationCanceledException) {} finally {checking.TryRemove(path,out _);} });}
    public void Dispose() {stop.Cancel();scanTimer?.Dispose();foreach(var w in watchers) w.Dispose();stop.Dispose();}
}
